      "Илья придержал край чертежа разводным ключом. Мира включила узкий фонарь и проследила лучом путь от метеошахты к центральному узлу. На карте виднелись два маршрута. Первый вёл к грузовому лифту, который Восс наверняка уже запер. Второй уходил на север через насосную станцию, затем поднимался по отдельной монтажной шахте вдоль силовых магистралей реакторного блока.",
