      {
        "type": "npc",
        "text": "«Я отнесу копии замеров врачам и старейшинам жилого блока, — ответила Мира. — Люди должны услышать это не только по громкой связи. Я покажу им калибровочную карточку и исходные данные прибора. Потом догоню вас у галереи. Не пытайтесь спорить с охраной от моего имени — сначала пусть они увидят цифры»."
      },
      "Ты сверил время на планшете. Виктор оценивал подход колонны менее чем в двадцать минут, и часть этого времени уже была потеряна на разговор. Оставалось выбрать способ пройти насосную: включить резервный агрегат и использовать его шум как прикрытие либо оставить оборудование в покое, сохранив тишину для скрытого подъёма.",
      "Перед тем как свернуть чертёж, ты заметил карандашную пометку возле монтажной шахты: «Ствол № 0 — не использовать при полной нагрузке реактора». Под ней стояла дата нулевого года и подпись инженера, которую ты не помнил. Почерк казался знакомым, почти твоим собственным. Ты сложил синьку и убрал её в планшет."
