        "label": "Осмотреть разорванный приказ Восса в корзине у лабораторного стола",
        "text": "На склеенных полосках приказа стоит подпись Артура Восса и дата двухлетней давности. В документе он поручает отправить группу Виктора на ретрансляционную вышку и официально провести её как погибшую при обвале ствола. Настоящая задача — скрытное наблюдение за северной дорогой. Приказ объясняет, почему Восс знал о чистом воздухе и присутствии людей на поверхности, но запрещал жителям подниматься.",
