        "text": "На ленте указаны кислород 20,7%, естественный радиационный фон и нулевая концентрация токсичных примесей. Данные получены после повторного цикла с независимой калибровкой и подписаны заводским ключом метеозонда. Это подтверждение можно предъявить совету жителей и бойцам охраны.",
