      "Илья стоял за корпусом трансформатора и держал ладонь поднятой. Он дождался, пока Мира уберёт алюминиевый кофр в сухую нишу, и только тогда прошептал:",
      {
        "type": "npc",
        "text": "«Трое, возможно четверо. Я видел не самих людей, а отражение приборов ночного видения на смотровой линзе. Они отключили камеры, но забыли, что у старого поста есть независимый тепловой датчик. Идут со стороны грузового ствола. Это не обычный патруль: двигаются без разговоров и проверяют каждый стык»."
      },
      "На экране вспыхнула вторая метка. Затем третья. Они двигались равномерно, с одинаковыми паузами у опор. Т2 вывел поверх изображения силуэты и показал, что у замыкающего бойца на плече закреплена цифровая рация с открытым аварийным каналом. Если удастся захватить её, вы сможете обратиться к постам без доступа к стационарному селектору.",
      {
        "type": "hero",
        "text": "«Нам нельзя позволить им добраться до метеошахты. Если Восс узнает, что Виктор подтвердил гибель второй колонны, он уничтожит запись и отключит все внешние каналы. Илья, найди клапан паровой магистрали. Мира, держись за трансформатором и не выходи на мостик»."
      },
      {
        "type": "npc",
        "text": "«Клапан здесь. Красный маховик открывает сброс во второй коллектор. Если подать пар в тоннель, ночная оптика ослепнет от тепловой засветки. Но давление нельзя держать долго: перегреем ближайший датчик и потеряем контроль над температурой», — ответил Илья."
      },
      "Ты ещё раз посмотрел на камеру. На её корпусе осталась свежая полоса от инструмента — кто-то не просто отключил питание, а физически повернул линзу к стене. Засада была подготовлена заранее, значит, гвардия Восса знала о вашем маршруте или получила приказ перехватить вас сразу после выхода из метеошахты.",
      "Над тоннелем послышался короткий металлический щелчок: кто-то проверял крепление нижней лестницы, стараясь не выдать себя голосом."
