        "text": "На главном газоанализаторе приточной вентиляции нулевого уровня горят зелёные индикаторы полной нормы, а стрелка расходомера воздуха отклонена вправо до упора — свежий воздух с поверхности уже начал поступать в верхний уровень комплекса через приоткрытый портал. Однако рядом с манометром мигает красная лампа «РАЗГЕРМЕТИЗАЦИЯ ВНЕШНЕГО ПЕРИМЕТРА // БИОЛОГИЧЕСКИЙ КОНТРОЛЬ ОТКЛЮЧЁН».",
