      "На металлическом настиле мостика отчётливо виднелись следы недавней обуви и узкая царапина от тяжёлого ящика, который протащили к пульту. Один из гвардейцев узнал тебя раньше второго: его взгляд задержался на титановом модуле у твоего пояса, затем скользнул к Воссу. В этой короткой паузе ты увидел, как рушится приказная вертикаль. Люди ещё не выбрали сторону окончательно, но уже перестали быть уверены, что прежняя власть имеет право требовать от них выстрела."
