    "t2Comment": "Смотри на глаза Артура Восса, Аэ́рхис, пока в динамиках диспетчерской звучит голос старшего колонны «Корунд-1» о захвате реакторного спуска и подавлении сопротивления. Иллюзия, на которой держалась вся его воля три года, рассыпается прямо сейчас — но человек, у которого рушится смысл жизни, может совершить самый непредсказуемый поступок.",
