      "В этот момент на центральном мониторе наружного наблюдения вспыхнули яркие белые пятна: из-за последнего поворота бетонного серпантина на разворотную площадку перед порталом вырвались три тяжёлых трёхосных бронетранспортёра с закрашенными бортовыми номерами и включёнными слепящими фарами-искателями.",
      "Головная машина «Корунд-1» не сбавила ход — она пошла на прямой разгон к приоткрытому проёму внешнего затвора, рассчитывая проскочить под кромкой бетонной плиты раньше, чем та успеет опуститься.",
