    "t2Comment": "Держись за поручень консоли, Аэ́рхис! При аварийном сбросе тормозные клапаны гидравлики открываются полностью, и сорок тонн армированного бетона падают вниз под собственным весом. Сейчас содрогнётся весь нулевой уровень.",
