      "В диспетчерской взвыла резкая, пронзительная сирена предупреждения о закрытии периметра. В глубине бетонных стен с оглушительным шипением сработали перепускные клапаны гидравлических цилиндров, и колоссальная сорокатонная плита внешнего затвора, на миг замерев в верхней точке, с нарастающим грохотом рухнула вниз по стальным направляющим.",
      "Сквозь толстое бронестекло смотрового окна было видно, как водитель головного бронетранспортёра «Корунд-1», заметив стремительно падающую бетонную стену, ударил по тормозам. Тяжёлая восьмиколёсная машина пошла юзом по мокрому весеннему асфальту, высекая снопы искр заблокированными колёсами, и остановилась всего в трёх метрах от порога в ту самую секунду, когда нижняя кромка затвора с чудовищным, сотрясающим весь бункер ударом врезалась в бетонный паз и намертво защёлкнулась на титановые ригели.",
      "От удара по бронированному стеклу диспетчерской пробежала мелкая дрожь, со светильников посыпалась сухая пыль, а в шлюзовой камере за переборкой снова воцарился искусственный полумрак аварийных ламп. Портал был закрыт вовремя.",
