      "Вибрация прошла через подошвы, поднялась по голеням и ударила в челюсть так, что на мгновение ты почувствовал металлический вкус во рту. Индикаторы на панели погасли один за другим, затем загорелась зелёная полоса механических ригелей. Камера наружного наблюдения автоматически переключилась на резервный обзор: за плитой поднималось облако бетонной пыли, а головная машина стояла под углом, с передними колёсами, вывернутыми к обочине. Ни один выстрел не последовал. Пока."
