        "text": "Частота рации Коршуна абсолютно идентична той, на которой выходили на связь люди из северных горных выработок за Вышгородом. Судя по всему, отряд Коршуна действительно наткнулся на остатки той самой второй автоколонны в северных шахтах, захватил их архивные коды и радиостанцию и пришёл к «BLACKOUT» по готовым координатам.",
