        "id": "insp_ch02_armory_optics_crate",
        "label": "Осмотреть ящик с оптическими приборами и специальным снаряжением на стеллаже",
        "text": "В герметичном пенале лежат компактный призменный бинокль с сеткой дальномера, две дымовые шашки белого дыма для прикрытия манёвра на открытой местности и несколько запасных обойм. Дымовая завеса на подъездной площадке сможет полностью ослепить наводчиков крупнокалиберных пулемётов на бронетранспортёрах Коршуна.",
