        "text": "Внутри ранца находятся четыре готовых кумулятивных заряда с дистанционным радиовзрывателем и подробная схема наступления отряда Коршуна, нарисованная на армейском планшете. Из схемы видно, что после подрыва вентиляционной шахты Коршун планировал стянуть всех пехотинцев к пролому, оставив у припаркованного у края обрыва топливозаправщика всего одного часового. Если устроить отвлекающий подрыв или дымовую завесу у заправщика, весь отряд на площадке охватит паника.",
