        "text": "Низкая каменная стенка высотой по пояс даёт идеальное укрытие и упор для стрельбы на дистанции сорока метров до головной машины Коршуна. В десяти метрах правее находится металлический отбойник, за которым припаркован тяжёлый бензовоз колонны; один точный выстрел зажигательным или трассирующим патроном в топливную горловину или установка дымовой шашки под его колёса мгновенно отсечёт отряд мародёров от пути отступления по серпантину.",
