        "text": "Дымовая завеса скрывает площадку от прицельного огня, но двое стрелков Коршуна укрылись за задними колёсами бензовоза. Любая очередь по стальной цистерне или рикошет рядом с ней может воспламенить пары топлива и повредить гидравлику портала. Стрелять в эту зону нельзя — противника нужно вытеснить с фланга.",
